23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	};
62	
63	/** Rounds to whole G in the MHPCO's favour, ignoring binary floating-point drift. */
64	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
65	
66	const quotePremium = (items: Item[]): number => {
67	  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
68	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
69	  return roundUpToWholeG(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
70	};
71	
72	export const runScenario = (scenario: Scenario): ScenarioResult => {
73	  return {
74	    results: scenario.steps.map((step) => ({
75	      premium: quotePremium((step as QuoteStep).items),
76	    })),
77	  };
78	};
